1	package tui
2	
3	import (
4		"fmt"
5		"io"
6		"os"
7		"strings"
8		"unicode/utf8"
9	
10		"github.com/charmbracelet/lipgloss"
11		xterm "github.com/charmbracelet/x/term"
12		"github.com/mattn/go-isatty"
13		"github.com/mattn/go-runewidth"
14	)
15	
16	// render.go is the line-oriented half of this package. The dashboard above it
17	// (tui.go) owns a full-screen bubbletea program; the commands people actually
18	// run — `setup`, `status` — write ordinary lines to a stream that may be a
19	// terminal, a pipe, a CI log, a systemd journal or a hook whose stdout is
20	// contractually empty. They still deserve colour, marks, spinners and bars when
21	// the destination can render them, and byte-stable plain text when it cannot.
22	//
23	// Both halves share one palette (Theme), so a component that is Good-coloured in
24	// the dashboard is the same colour on a setup line. What they do NOT share is
25	// lipgloss's implicit renderer: lipgloss decides colour from a package-global
26	// profile bound to os.Stdout, which makes styled output untestable (it depends
27	// on how the TEST process was started) and wrong for a command writing to
28	// stderr. Caps below is an explicit, injectable answer to "what can THIS stream
29	// render", and every escape sequence in this file is gated on it.
30	
31	// Caps is what a destination stream can render.
32	type Caps struct {
33		// TTY reports whether the stream is a terminal. It gates every in-place
34		// repaint: a pipe gets whole lines and nothing else.
35		TTY bool
36		// Color reports whether ANSI colour may be emitted. TTY implies nothing —
37		// NO_COLOR, TERM=dumb and a non-terminal each turn it off independently.
38		Color bool
39		// Unicode reports whether non-ASCII glyphs will render. A terminal whose
40		// locale is not UTF-8 draws them as replacement boxes, which is where the
41		// stray "□" in the spinner and the em dashes came from.
42		Unicode bool
43		// Width is the usable line width; 0 means unknown (do not truncate).
44		Width int
45	}
46	
47	// PlainCaps is the byte-stable mode: whole lines, ASCII, no colour. Every
48	// non-terminal destination resolves to exactly this, which is what makes the
49	// plain path safe to assert on in tests and safe to pipe into a log.
50	func PlainCaps() Caps { return Caps{} }
51	
52	// EnvLookup is os.LookupEnv's shape. The "found" half matters: NO_COLOR is
53	// honoured by PRESENCE, so NO_COLOR= (empty) must still disable colour, and a
54	// plain getenv cannot tell that from unset.
55	type EnvLookup func(string) (string, bool)
56	
57	// DetectCaps resolves the capabilities of w from the process environment.
58	func DetectCaps(w io.Writer) Caps { return DetectCapsWithEnv(w, os.LookupEnv) }
59	
60	// DetectCapsWithEnv is DetectCaps with the environment injected, so the
61	// TTY/NO_COLOR/locale matrix is testable without mutating process state.
62	func DetectCapsWithEnv(w io.Writer, lookup EnvLookup) Caps {
63		file, ok := w.(*os.File)
64		if !ok || file == nil {
65			return PlainCaps()
66		}
67		fd := file.Fd()
68		if !isatty.IsTerminal(fd) && !isatty.IsCygwinTerminal(fd) {
69			return PlainCaps()
70		}
71		caps := terminalCaps(lookup)
72		if caps.TTY {
73			caps.Width = terminalWidth(fd, func(key string) string { value, _ := lookup(key); return value })
74		}
75		return caps
76	}
77	
78	// terminalCaps resolves environment policy after the caller verifies a terminal.
79	func terminalCaps(lookup EnvLookup) Caps {
80		if lookup == nil {
81			lookup = func(string) (string, bool) { return "", false }
82		}
83		getenv := func(key string) string { value, _ := lookup(key); return value }
84		if !SupportsFullScreen(getenv) {
85			return PlainCaps()
86		}
87		caps := Caps{TTY: true, Unicode: localeIsUTF8(getenv)}
88		// NO_COLOR is defined by presence, including an empty value.
89		if _, noColor := lookup("NO_COLOR"); !noColor {
90			caps.Color = true
91		}
92		return caps
93	}
94	
95	// SupportsFullScreen reports whether TERM describes a terminal that can be
96	// driven with escape sequences at all. TERM=dumb and an unset TERM do not: a
97	// dumb terminal has no cursor addressing, no alternate screen and no SGR, so
98	// anything written for one arrives as literal escape bytes.
99	//
100	// It gates both halves of this package. The line renderer above drops to
101	// PlainCaps; the dashboard declines to start and the caller prints the plain
102	// summary instead — otherwise `dash` on TERM=dumb pushed \x1b[?1049h, a
103	// rounded-border layout and 256-colour SGR at a terminal that renders every
104	// byte of it as text.
105	func SupportsFullScreen(getenv func(string) string) bool {
106		if getenv == nil {
107			return false
108		}
109		term := strings.TrimSpace(getenv("TERM"))
110		return term != "" && term != "dumb"
111	}
112	
113	// terminalWidth resolves the usable line width for a terminal, in order of
114	// authority: the kernel, then COLUMNS, then a conservative 80.
115	//
116	// The fallback is not optional. On a terminal of UNKNOWN width the in-place
117	// line is not truncated, so a long label wraps — and the carriage-return erase
118	// only ever clears the last physical row, leaving the wrapped remainder on
119	// screen under the final line. That is precisely the "every phase prints twice"
120	// report. Guessing 80 can clip a label on a wide terminal; not guessing
121	// reintroduces the bug.
122	func terminalWidth(fd uintptr, getenv func(string) string) int {
123		if width, _, err := xterm.GetSize(fd); err == nil && width > 0 {
124			return width
125		}
126		if columns := strings.TrimSpace(getenv("COLUMNS")); columns != "" {
127			width := 0
128			for _, ch := range columns {
129				if ch < '0' || ch > '9' {
130					width = 0
131					break
132				}
133				width = width*10 + int(ch-'0')
134			}
135			if width > 0 {
136				return width
137			}
138		}
139		return 80
140	}
141	
142	// localeIsUTF8 reports whether the locale promises UTF-8 output. The check is
143	// deliberately conservative: an unset or non-UTF-8 locale falls back to ASCII
144	// glyphs rather than gambling that the font has a spinner in it.
145	func localeIsUTF8(getenv func(string) string) bool {
146		for _, key := range []string{"LC_ALL", "LC_CTYPE", "LANG"} {
147			value := strings.TrimSpace(getenv(key))
148			if value == "" {
149				continue
150			}
151			lowered := strings.ToLower(value)
152			return strings.Contains(lowered, "utf-8") || strings.Contains(lowered, "utf8")
153		}
154		// Windows Terminal and the VS Code terminal are UTF-8 without ever setting
155		// a POSIX locale.
156		return strings.TrimSpace(getenv("WT_SESSION")) != "" ||
157			strings.EqualFold(strings.TrimSpace(getenv("TERM_PROGRAM")), "vscode")
158	}
159	
160	// Mark is a per-outcome status glyph.
161	type Mark int
162	
163	const (
164		// MarkDone is a component that built.
165		MarkDone Mark = iota
166		// MarkFailed is a component that was attempted and blew up.
167		MarkFailed
168		// MarkSkipped is a component that was deliberately not attempted.
169		MarkSkipped
170		// MarkPending is a component that has not reported yet.
171		MarkPending
172	)
173	
174	// Renderer turns semantic pieces (a mark, a bar, a phase colour) into bytes
175	// appropriate for one destination stream.
176	type Renderer struct {
177		theme Theme
178		caps  Caps
179	}
180	
181	// NewRenderer builds a renderer for w, detecting what w can render.
182	func NewRenderer(w io.Writer) *Renderer {
183		theme, _ := ThemeByName(os.Getenv("ENTIRE_BRAIN_THEME"))
184		return &Renderer{theme: theme, caps: DetectCaps(w)}
185	}
186	
187	// NewRendererWith builds a renderer with an explicit theme and capabilities.
188	func NewRendererWith(theme Theme, caps Caps) *Renderer {
189		return &Renderer{theme: theme, caps: caps}
190	}
191	
192	// Caps reports what this renderer's destination can render.
193	func (r *Renderer) Caps() Caps {
194		if r == nil {
195			return PlainCaps()
196		}
197		return r.caps
198	}
199	
200	// Theme reports the palette in use.
201	func (r *Renderer) Theme() Theme {
202		if r == nil {
203			return themes["default"]
204		}
205		return r.theme
206	}
207	
208	// Paint wraps s in the SGR sequence for c, or returns s untouched when colour
209	// is off. It emits the escape itself rather than delegating to lipgloss because
210	// lipgloss resolves colour from a process-global profile bound to os.Stdout —
211	// which is neither the stream we are writing to nor stable under `go test`.
212	func (r *Renderer) Paint(c lipgloss.Color, s string) string {
213		if r == nil || !r.caps.Color || s == "" {
214			return s
215		}
216		seq := ansiForeground(c)
217		if seq == "" {
218			return s
219		}
220		return seq + s + "\x1b[0m"
221	}
222	
223	// Bold renders s bold when the stream supports styling.
224	func (r *Renderer) Bold(s string) string {
225		if r == nil || !r.caps.Color || s == "" {
226			return s
227		}
228		return "\x1b[1m" + s + "\x1b[0m"
229	}
230	
231	// Dim renders s in the muted palette colour.
232	func (r *Renderer) Dim(s string) string { return r.Paint(r.Theme().Dim, s) }
233	
234	// spinnerFramesUnicode is the braille spinner; spinnerFramesASCII is the
235	// fallback for a terminal whose locale cannot promise UTF-8. The ASCII set is
236	// the classic four-frame bar, which is what the "-\|/" contract in the CLI
237	// expects.
238	var (
239		spinnerFramesUnicode = []string{"⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"}
240		spinnerFramesASCII   = []string{"-", "\\", "|", "/"}
241	)
242	
243	// Spinner returns the frame for tick. It is pure: the caller owns the clock,
244	// so a test can assert frame N without sleeping.
245	func (r *Renderer) Spinner(tick int) string {
246		frames := spinnerFramesASCII
247		if r != nil && r.caps.Unicode {
248			frames = spinnerFramesUnicode
249		}
250		if tick < 0 {
251			tick = -tick
252		}
253		return frames[tick%len(frames)]
254	}
255	
256	// SpinnerFrames reports the glyph set in use, for tests and for callers that
257	// need to size a column.
258	func (r *Renderer) SpinnerFrames() []string {
259		if r != nil && r.caps.Unicode {
260			return append([]string(nil), spinnerFramesUnicode...)
261		}
262		return append([]string(nil), spinnerFramesASCII...)
263	}
264	
265	// Mark renders an outcome glyph, coloured by outcome.
266	func (r *Renderer) Mark(m Mark) string {
267		glyph, color := r.markGlyph(m)
268		return r.Paint(color, glyph)
269	}
270	
271	// MarkGlyph is the outcome glyph WITHOUT colour, for callers that have to
272	// budget a line's width before painting it. Measuring the painted form would
273	// charge the SGR bytes as display width and shrink the line for no reason —
274	// the same reason liveLine measures the plain spinner frame rather than the
275	// coloured one.
276	func (r *Renderer) MarkGlyph(m Mark) string {
277		glyph, _ := r.markGlyph(m)
278		return glyph
279	}
280	
281	func (r *Renderer) markGlyph(m Mark) (string, lipgloss.Color) {
282		theme := r.Theme()
283		unicode := r != nil && r.caps.Unicode
284		switch m {
285		case MarkDone:
286			if unicode {
287				return "✓", theme.Good
288			}
289			return "+", theme.Good
290		case MarkFailed:
291			if unicode {
292				return "✗", theme.Bad
293			}
294			return "x", theme.Bad
295		case MarkSkipped:
296			if unicode {
297				return "−", theme.Dim
298			}
299			return "-", theme.Dim
300		default:
301			if unicode {
302				return "·", theme.Dim
303			}
304			return ".", theme.Dim
305		}
306	}
307	
308	// Dash is an em dash where the locale can draw one and a plain hyphen where it
309	// cannot. The stray "□" people saw mid-line was an em dash in a terminal whose
310	// locale was not UTF-8.
311	func (r *Renderer) Dash() string {
312		if r != nil && r.caps.Unicode {
313			return "—"
314		}
315		return "--"
316	}
317	
318	// Bullet is the mid-dot separator where the locale can draw one and a pipe
319	// where it cannot. Same reasoning as Dash: a hard-coded "\u00b7" renders as a
320	// replacement box on a terminal whose locale is not UTF-8.
321	func (r *Renderer) Bullet() string {
322		if r != nil && r.caps.Unicode {
323			return "\u00b7"
324		}
325		return "|"
326	}
327	
328	// Bar renders a determinate progress bar of the given cell width, coloured as a
329	// red -> amber -> green ramp ACROSS the bar: each filled cell takes the colour
330	// of its own position, so the bar visibly warms as it fills instead of flipping
331	// colour in one step. total <= 0 is indeterminate and renders as an empty
332	// track, because a bar that cannot say how full it is must not imply zero.
333	func (r *Renderer) Bar(done, total, width int) string {
334		if width <= 0 {
335			return ""
336		}
337		full, empty := "#", "."
338		if r != nil && r.caps.Unicode {
339			full, empty = "█", "░"
340		}
341		if total <= 0 {
342			return r.Dim(strings.Repeat(empty, width))
343		}
344		if done < 0 {
345			done = 0
346		}
347		if done > total {
348			done = total
349		}
350		filled := done * width / total
351		// Any real progress must light at least one cell, or a 1/618 export looks
352		// identical to a 0/618 one for the first ninety seconds.
353		if filled == 0 && done > 0 {
354			filled = 1
355		}
356		var b strings.Builder
357		for i := 0; i < filled; i++ {
358			b.WriteString(r.Paint(r.rampColor(float64(i+1)/float64(width)), full))
359		}
360		if rest := width - filled; rest > 0 {
361			b.WriteString(r.Dim(strings.Repeat(empty, rest)))
362		}
363		return b.String()
364	}
365	
366	// rampColor maps a 0..1 position onto the palette's bad/ok/good ramp.
367	func (r *Renderer) rampColor(fraction float64) lipgloss.Color {
368		theme := r.Theme()
369		switch {
370		case fraction < 0.34:
371			return theme.Bad
372		case fraction < 0.67:
373			return theme.OK
374		default:
375			return theme.Good
376		}
377	}
378	
379	// Ratio renders "done/total" coloured by completeness, so a count reads the
380	// same way as the bar beside it.
381	func (r *Renderer) Ratio(done, total int) string {
382		text := fmt.Sprintf("%d/%d", done, total)
383		if total <= 0 {
384			return r.Dim(text)
385		}
386		return r.Paint(r.rampColor(float64(done)/float64(total)), text)
387	}
388	
389	// Truncate clips s to the renderer's line width, measured in display cells so a
390	// CJK or emoji-bearing label is not cut mid-glyph. A live line that WRAPS is
391	// the reason phase lines looked doubled: the carriage-return rewrite only ever
392	// clears the last physical row, so the wrapped first row stays on screen and
393	// the final line prints under it.
394	func (r *Renderer) Truncate(s string) string {
395		if r == nil || r.caps.Width <= 0 {
396			return s
397		}
398		// One cell of slack: writing into the last column makes some terminals wrap
399		// eagerly, which is the very thing being avoided.
400		return r.TruncateTo(s, r.caps.Width-1)
401	}
402	
403	// TruncateTo clips s to limit display cells. It must be given PLAIN text: the
404	// measurement counts runes, so an already-coloured string would have its escape
405	// bytes charged as width. Callers that colour a line build it as plain text,
406	// truncate here, and colour the pieces afterwards.
407	func (r *Renderer) TruncateTo(s string, limit int) string {
408		if limit <= 0 {
409			return ""
410		}
411		tail := "..."
412		if r != nil && r.caps.Unicode {
413			tail = "…"
414		}
415		if limit <= 1 {
416			tail = ""
417		} else if runewidth.StringWidth(tail) > limit {
418			tail = ""
419		}
420		return truncateANSI(s, limit, tail)
421	}
422	
423	// truncateANSI truncates to a VISIBLE cell count, never cutting inside an
424	// escape sequence, and closes a colour the cut would have left open.
425	//
426	// runewidth counts an escape's bytes as cells and will happily cut through the
427	// middle of one. Both are wrong on a string that is already painted, and the
428	// second is the worse of the two: a terminal handed `ESC [ 3` with no final
429	// byte waits for the rest of the sequence and swallows whatever follows it.
430	// Observed live on setup's progress bar, which composes a per-cell coloured
431	// bar and hands it on as a label for this function to budget:
432	//
433	//	ESC[38;5;203m█ESC[0m ... ESC[3…ESC[0m
434	//	                          ^^^^^ cut mid-sequence, terminal eats the rest
435	func truncateANSI(s string, limit int, tail string) string {
436		if limit <= 0 {
437			return ""
438		}
439		if ansiVisibleWidth(s) <= limit {
440			return s
441		}
442		budget := limit - runewidth.StringWidth(tail)
443		if budget < 0 {
444			budget = 0
445		}
446		var b strings.Builder
447		width, open := 0, false
448		for i := 0; i < len(s); {
449			if s[i] == 0x1b {
450				// Copy the whole sequence or none of it; never a prefix.
451				j := skipANSI(s, i)
452				seq := s[i:j]
453				b.WriteString(seq)
454				// Track whether a colour is left open, so the cut can close it.
455				if strings.HasSuffix(seq, "m") {
456					open = seq != "\x1b[0m" && seq != "\x1b[m"
457				}
458				i = j
459				continue
460			}
461			rn, size := utf8.DecodeRuneInString(s[i:])
462			w := runewidth.RuneWidth(rn)
463			if width+w > budget {
464				break
465			}
466			b.WriteString(s[i : i+size])
467			width += w
468			i += size
469		}
470		b.WriteString(tail)
471		if open {
472			b.WriteString("\x1b[0m")
473		}
474		return b.String()
475	}
476	
477	// ansiVisibleWidth is StringWidth with escape sequences charged nothing.
478	func ansiVisibleWidth(s string) int {
479		width := 0
480		for i := 0; i < len(s); {
481			if s[i] == 0x1b {
482				i = skipANSI(s, i)
483				continue
484			}
485			rn, size := utf8.DecodeRuneInString(s[i:])
486			width += runewidth.RuneWidth(rn)
487			i += size
488		}
489		return width
490	}
491	
492	// skipANSI returns the index just past the escape sequence starting at i.
493	//
494	// The shape is ESC '[' <params 0x30-0x3f> <intermediates 0x20-0x2f> <final
495	// 0x40-0x7e>. The '[' must be stepped over BEFORE hunting the final byte:
496	// 0x5b is itself inside the final-byte range, so a scanner that does not
497	// will stop on the bracket and read the parameters as visible text. That is
498	// not hypothetical — it is the bug the first draft of this function shipped,
499	// which measured "\x1b[38;5;45m" as eight visible cells.
500	func skipANSI(s string, i int) int {
501		j := i + 1
502		if j < len(s) && s[j] == '[' {
503			j++
504			for j < len(s) && s[j] >= 0x30 && s[j] <= 0x3f {
505				j++
506			}
507			for j < len(s) && s[j] >= 0x20 && s[j] <= 0x2f {
508				j++
509			}
510		}
511		if j < len(s) && isANSIFinalByte(s[j]) {
512			j++
513		}
514		return j
515	}
516	
517	// isANSIFinalByte reports the byte that ends a CSI sequence (@ through ~).
518	func isANSIFinalByte(b byte) bool { return b >= 0x40 && b <= 0x7e }
519	
520	// Width reports the usable line width, 0 when unknown.
521	func (r *Renderer) Width() int {
522		if r == nil {
523			return 0
524		}
525		return r.caps.Width
526	}
527	
528	// Phase names the stage of onboarding a line belongs to. Colour-coding by phase
529	// is what makes a scrolling setup readable at a glance: the instant core, the
530	// background backfill and the daemon are three different kinds of work with
531	// three different cost profiles, and a reader should not have to parse the text
532	// to tell which one a line came from.
533	type Phase int
534	
535	const (
536		// PhaseNeutral is an uncategorised line.
537		PhaseNeutral Phase = iota
538		// PhaseInstant is the free, blocking, deterministic core.
539		PhaseInstant
540		// PhaseBackfill is the detached, token-spending fact backfill.
541		PhaseBackfill
542		// PhaseDaemon is workspace registration and the background watcher.
543		PhaseDaemon
544		// PhaseDone marks a completed step.
545		PhaseDone
546		// PhaseSkipped marks a step that was deliberately not run.
547		PhaseSkipped
548		// PhaseFailed marks a step that was attempted and failed.
549		PhaseFailed
550	)
551	
552	// PhaseColor resolves the palette entry for a phase.
553	func (r *Renderer) PhaseColor(p Phase) lipgloss.Color {
554		theme := r.Theme()
555		switch p {
556		case PhaseInstant:
557			return theme.Link
558		case PhaseBackfill:
559			return theme.Alt
560		case PhaseDaemon:
561			return theme.Accent
562		case PhaseDone:
563			return theme.Good
564		case PhaseSkipped:
565			return theme.Flag
566		case PhaseFailed:
567			return theme.Bad
568		default:
569			return theme.Text
570		}
571	}
572	
573	// PhasePaint colours s for a phase.
574	func (r *Renderer) PhasePaint(p Phase, s string) string {
575		if p == PhaseNeutral {
576			return s
577		}
578		return r.Paint(r.PhaseColor(p), s)
579	}
580	
581	// ansiForeground converts a palette colour into an SGR foreground sequence.
582	// lipgloss.Color carries either an xterm-256 index ("214") or a hex triplet
583	// ("#f9e2af"); both themes in this package use both forms.
584	func ansiForeground(c lipgloss.Color) string {
585		value := strings.TrimSpace(string(c))
586		if value == "" {
587			return ""
588		}
589		if strings.HasPrefix(value, "#") {
590			r, g, b, ok := parseHexColor(value)
591			if !ok {
592				return ""
593			}
594			return fmt.Sprintf("\x1b[38;2;%d;%d;%dm", r, g, b)
595		}
596		index := 0
597		for _, ch := range value {
598			if ch < '0' || ch > '9' {
599				return ""
600			}
601			index = index*10 + int(ch-'0')
602			if index > 255 {
603				return ""
604			}
605		}
606		return fmt.Sprintf("\x1b[38;5;%dm", index)
607	}
608	
609	func parseHexColor(value string) (int, int, int, bool) {
610		digits := value[1:]
611		if len(digits) == 3 {
612			expanded := make([]byte, 0, 6)
613			for i := 0; i < 3; i++ {
614				expanded = append(expanded, digits[i], digits[i])
615			}
616			digits = string(expanded)
617		}
618		if len(digits) != 6 {
619			return 0, 0, 0, false
620		}
621		out := [3]int{}
622		for i := 0; i < 3; i++ {
623			hi, ok := hexNibble(digits[i*2])
624			if !ok {
625				return 0, 0, 0, false
626			}
627			lo, ok := hexNibble(digits[i*2+1])
628			if !ok {
629				return 0, 0, 0, false
630			}
631			out[i] = hi*16 + lo
632		}
633		return out[0], out[1], out[2], true
634	}
635	
636	func hexNibble(b byte) (int, bool) {
637		switch {
638		case b >= '0' && b <= '9':
639			return int(b - '0'), true
640		case b >= 'a' && b <= 'f':
641			return int(b-'a') + 10, true
642		case b >= 'A' && b <= 'F':
643			return int(b-'A') + 10, true
644		}
645		return 0, false
646	}
