package cli

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
)

// planTranscriptCacheSweep proves each live cached transcript can be recovered
// locally before the export switches storage modes. A missing/promisor-only
// source must never turn migration into loss of the only readable copy.
// Unlisted files are stale exports. Exclusion is reversible, so excluded
// sessions need the same recovery proof as every other legacy cached session.
func planTranscriptCacheSweep(ctx context.Context, runner CommandRunner, brainDir, repoDir string) (*historySessionInventory, error) {
	if _, err := os.Lstat(brainDir); os.IsNotExist(err) {
		return nil, nil
	}
	inventory, err := collectHistorySessionInventoryMode(ctx, brainDir, true)
	if errors.Is(err, errHistorySessionsRootMissing) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	success := false
	defer func() {
		if !success {
			_ = inventory.Close()
		}
	}()
	manifest, err := loadBrainManifest(brainDir)
	if err != nil {
		return nil, err
	}
	sessions := historySessionByTranscriptPath(manifest)
	if _, err := loadSessionReadGuard(brainDir, manifest); err != nil {
		return nil, err
	}
	store := newTranscriptStore(runner, brainDir)
	// Persistent brains are shared by worktrees; the previous exporter's
	// recorded worktree may have been removed since the cache was written.
	store.repoDir = repoDir
	backed := checkpointBackedSessions(manifest)
	var retained map[string]bool
	retain := func(rel, reason string) {
		fmt.Fprintf(os.Stderr, "warning: retain transcript cache: %s for %s; keeping the cached copy\n", reason, rel)
		if retained == nil {
			retained = make(map[string]bool)
		}
		retained[rel] = true
	}
	for _, file := range inventory.files {
		if _, live := sessions[file.Rel]; !live {
			continue
		}
		location, snapshot, err := store.lookupLocation(ctx, file.Rel)
		if err != nil {
			if backed {
				retain(file.Rel, "checkpoint copy is unavailable")
				continue
			}
			return nil, fmt.Errorf("retain transcript cache: %w", err)
		}
		data, err := readSnapshotTranscriptFromSource(ctx, runner, snapshot, location.sourceKey, location.sourcePath)
		if err != nil {
			if backed {
				retain(file.Rel, "checkpoint copy is unreadable")
				continue
			}
			return nil, fmt.Errorf("retain transcript cache for %s: %w", file.Rel, err)
		}
		cached, _, err := readHistorySessionInventoryFile(ctx, inventory, file)
		if err != nil {
			return nil, err
		}
		switch {
		case bytes.HasPrefix(data, cached):
			// The checkpoint holds every cached byte (equal, or the
			// append-only transcript ran ahead of the last disk export), so
			// the file is recoverable and safe to sweep.
		case bytes.HasPrefix(cached, data):
			// The disk export ran ahead of the last checkpoint. Keep the
			// file out of the sweep instead of blocking every future export;
			// a later checkpoint reconciles it and the next sweep collects
			// it. Checkpoint-backed exports repeat this proof so the file is
			// never deleted while it still holds the only copy of the tail.
			retain(file.Rel, "cached transcript is newer than its checkpoint")
		case backed:
			// A divergent override of a checkpoint-backed session is an
			// untrusted stray; sweeping it is the established cleanup.
		default:
			return nil, fmt.Errorf("retain transcript cache: checkpoint bytes differ from %s", file.Rel)
		}
	}
	if len(retained) > 0 {
		kept := inventory.files[:0]
		for _, file := range inventory.files {
			if !retained[file.Rel] {
				kept = append(kept, file)
			}
		}
		inventory.files = kept
	}
	success = true
	return inventory, nil
}

// sweepTranscriptCache removes only the descriptor-bound files validated by the
// migration preflight. The caller holds the brain write lock and has published
// the checkpoint-backed manifest. Directories are removed only when empty.
func sweepTranscriptCache(ctx context.Context, inventory *historySessionInventory) error {
	if inventory == nil {
		return nil
	}
	current, err := collectHistorySessionInventoryMode(ctx, inventory.brainDir, true)
	if err != nil {
		return err
	}
	unchanged := inventory.sameMembership(current)
	_ = current.Close()
	if !unchanged {
		return fmt.Errorf("%s: transcript cache changed before migration sweep", memoryErrSourceStale)
	}
	if err := inventory.validateAll(ctx); err != nil {
		return err
	}
	for _, file := range inventory.files {
		if err := inventory.validateFileMembership(ctx, file); err != nil {
			return err
		}
		if err := inventory.root.Remove(file.Rel); err != nil {
			return err
		}
	}
	for i := len(inventory.entries) - 1; i >= 0; i-- {
		if inventory.entries[i].Mode.IsDir() {
			// A nonempty directory may contain non-transcript artifacts.
			_ = inventory.root.Remove(inventory.entries[i].Rel)
		}
	}
	return nil
}

package cli

import (
	"context"
	"fmt"
	"os"
	"strings"

	"github.com/entireio/entire-brain/internal/apiurl"
	"github.com/entireio/entire-brain/internal/repoid"
)

// envBrainAllowHosted is the legacy env opt-in for hosted egress, kept as a
// deprecated consent path so scripts written against it keep working. New
// setups should use `entire brain connect` or explicit target flags.
const envBrainAllowHosted = "ENTIRE_BRAIN_ALLOW_HOSTED"

// manualHostedTarget is the resolved destination for a manual hosted command
// (publish, facts sync --facts-backend=http, facts proposals).
type manualHostedTarget struct {
	repoID  string
	baseURL string
	token   string
}

// resolveManualHostedTarget resolves where a manual hosted command may send
// data, per field: explicit flag > env override > the connected binding
// (COR-2143). The binding contributes only while the repo is connected — an
// opt-out or absent binding never fills a field, so on a disconnected repo the
// command refuses unless the caller supplies the full target explicitly (the
// operator escape hatch). It performs no network call except token minting,
// which happens only after the target itself is fully resolved and validated.
//
// The token is minted through the host CLI only when the effective base URL is
// the connected binding's own — a minted login token must never be sent to a
// host the user pointed at explicitly, only to the one they connected to.
func resolveManualHostedTarget(ctx context.Context, opts Options, brainDir, repoDir, command string, flagRepoID, flagAPIURL, flagToken string) (manualHostedTarget, error) {
	var t manualHostedTarget
	var binding hostedRepoBinding
	connected := false
	if brainDir != "" {
		b, present, err := readHostedRepoBinding(brainDir)
		if err == nil && present && !b.OptedOut {
			binding, connected = b, true
		}
	}

	// Consent gate: ambient ENTIRE_* environment variables alone never
	// authorize hosted egress — a machine that exports them for other tooling
	// must not start uploading brain data because a command ran. Consent is the
	// connected binding, an explicit target flag on this invocation, or the
	// legacy ENTIRE_BRAIN_ALLOW_HOSTED opt-in (deprecated, honored for
	// backwards compatibility). Checked before any field resolution, so a
	// refusal is guaranteed egress-free.
	explicitFlag := strings.TrimSpace(flagRepoID) != "" || strings.TrimSpace(flagAPIURL) != "" || strings.TrimSpace(flagToken) != ""
	if !connected && !explicitFlag {
		if !envBool(envBrainAllowHosted) {
			return t, fmt.Errorf("%s: hosted egress is opt-in and this repo is not connected; run '%s', pass --repo-id/--api-url/--token explicitly, or set %s=1 (deprecated) to use the ENTIRE_* environment variables", command, brainInvocation(os.LookupEnv, "connect"), envBrainAllowHosted)
		}
		if _, seen := securityToggleWarned.LoadOrStore(envBrainAllowHosted+":deprecated", struct{}{}); !seen {
			fmt.Fprintf(os.Stderr, "warning: %s is deprecated; run '%s' or pass explicit target flags\n", envBrainAllowHosted, brainInvocation(os.LookupEnv, "connect"))
		}
	}

	t.repoID = publishFlagOrEnv(flagRepoID, envRepoID)
	if t.repoID == "" && connected {
		t.repoID = binding.RepoID
	}
	if t.repoID == "" {
		return t, fmt.Errorf("%s: target repo id is required; run '%s', or set --repo-id or %s", command, brainInvocation(os.LookupEnv, "connect"), envRepoID)
	}
	if err := repoid.Validate(t.repoID); err != nil {
		return t, fmt.Errorf("%s: %w", command, err)
	}

	t.baseURL = publishFlagOrEnv(flagAPIURL, envAPIBaseURL)
	if t.baseURL == "" && connected {
		t.baseURL = binding.BaseURL
	}
	if t.baseURL == "" {
		return t, fmt.Errorf("%s: API base URL is required; run '%s', or set --api-url or %s", command, brainInvocation(os.LookupEnv, "connect"), envAPIBaseURL)
	}
	baseURL, err := apiurl.Validate(t.baseURL)
	if err != nil {
		return t, fmt.Errorf("%s: %w", command, err)
	}
	t.baseURL = baseURL

	t.token = publishFlagOrEnv(flagToken, envAPIToken)
	if t.token == "" {
		if !connected || strings.TrimRight(t.baseURL, "/") != binding.BaseURL {
			return t, fmt.Errorf("%s: API token is required; set --token or %s (minted automatically when the target is the connected binding)", command, envAPIToken)
		}
		if repoDir == "" {
			repoDir = "."
		}
		t.token, err = mintHostedToken(ctx, opts.Runner, repoDir, hostEntireBinary)
		if err != nil {
			return t, fmt.Errorf("%s: %w", command, err)
		}
	}
	return t, nil
}

