12	
13	// planTranscriptCacheSweep proves each live cached transcript can be recovered
14	// locally before the export switches storage modes. A missing/promisor-only
15	// source must never turn migration into loss of the only readable copy.
16	// Unlisted files are stale exports. Exclusion is reversible, so excluded
17	// sessions need the same recovery proof as every other legacy cached session.
18	func planTranscriptCacheSweep(ctx context.Context, runner CommandRunner, brainDir, repoDir string) (*historySessionInventory, error) {
19		if _, err := os.Lstat(brainDir); os.IsNotExist(err) {
20			return nil, nil
21		}
22		inventory, err := collectHistorySessionInventoryMode(ctx, brainDir, true)
23		if errors.Is(err, errHistorySessionsRootMissing) {
24			return nil, nil
25		}
26		if err != nil {
27			return nil, err
28		}
29		success := false
30		defer func() {
31			if !success {
32				_ = inventory.Close()
33			}
34		}()
35		manifest, err := loadBrainManifest(brainDir)
36		if err != nil {
37			return nil, err
38		}
39		sessions := historySessionByTranscriptPath(manifest)
40		if _, err := loadSessionReadGuard(brainDir, manifest); err != nil {
41			return nil, err
42		}
43		store := newTranscriptStore(runner, brainDir)
44		// Persistent brains are shared by worktrees; the previous exporter's
45		// recorded worktree may have been removed since the cache was written.
46		store.repoDir = repoDir
47		backed := checkpointBackedSessions(manifest)
48		var retained map[string]bool
49		retain := func(rel, reason string) {
50			tui.Warnf(os.Stderr, "retain transcript cache: %s for %s; keeping the cached copy", reason, rel)
51			if retained == nil {
52				retained = make(map[string]bool)
53			}
54			retained[rel] = true
55		}
56		for _, file := range inventory.files {
57			if _, live := sessions[file.Rel]; !live {
58				continue
59			}
60			location, snapshot, err := store.lookupLocation(ctx, file.Rel)
61			if err != nil {
62				if backed {
63					retain(file.Rel, "checkpoint copy is unavailable")
64					continue
65				}
66				return nil, fmt.Errorf("retain transcript cache: %w", err)
67			}
68			data, err := readSnapshotTranscriptFromSource(ctx, runner, snapshot, location.sourceKey, location.sourcePath)
69			if err != nil {
70				if backed {
71					retain(file.Rel, "checkpoint copy is unreadable")
72					continue
73				}
74				return nil, fmt.Errorf("retain transcript cache for %s: %w", file.Rel, err)
75			}
76			cached, _, err := readHistorySessionInventoryFile(ctx, inventory, file)
77			if err != nil {
78				return nil, err
79			}
80			switch {
81			case bytes.HasPrefix(data, cached):
82				// The checkpoint holds every cached byte (equal, or the
83				// append-only transcript ran ahead of the last disk export), so
84				// the file is recoverable and safe to sweep.
85			case bytes.HasPrefix(cached, data):
86				// The disk export ran ahead of the last checkpoint. Keep the
87				// file out of the sweep instead of blocking every future export;
88				// a later checkpoint reconciles it and the next sweep collects
89				// it. Checkpoint-backed exports repeat this proof so the file is
90				// never deleted while it still holds the only copy of the tail.
91				retain(file.Rel, "cached transcript is newer than its checkpoint")
92			case backed:
93				// A divergent override of a checkpoint-backed session is an
94				// untrusted stray; sweeping it is the established cleanup.
95			default:
96				return nil, fmt.Errorf("retain transcript cache: checkpoint bytes differ from %s", file.Rel)
97			}
98		}
99		if len(retained) > 0 {
100			kept := inventory.files[:0]
101			for _, file := range inventory.files {
102				if !retained[file.Rel] {
103					kept = append(kept, file)
104				}
105			}
106			inventory.files = kept
107		}
108		success = true
109		return inventory, nil
110	}
111	
112	// sweepTranscriptCache removes only the descriptor-bound files validated by the
113	// migration preflight. The caller holds the brain write lock and has published
114	// the checkpoint-backed manifest. Directories are removed only when empty.
115	func sweepTranscriptCache(ctx context.Context, inventory *historySessionInventory) error {
116		if inventory == nil {
117			return nil
118		}
119		current, err := collectHistorySessionInventoryMode(ctx, inventory.brainDir, true)
120		if err != nil {
121			return err
122		}
123		unchanged := inventory.sameMembership(current)
124		_ = current.Close()
125		if !unchanged {
126			return fmt.Errorf("%s: transcript cache changed before migration sweep", memoryErrSourceStale)
127		}
128		if err := inventory.validateAll(ctx); err != nil {
129			return err
130		}
131		for _, file := range inventory.files {
132			if err := inventory.validateFileMembership(ctx, file); err != nil {
133				return err
134			}
135			if err := inventory.root.Remove(file.Rel); err != nil {
136				return err
137			}
138		}
139		for i := len(inventory.entries) - 1; i >= 0; i-- {
140			if inventory.entries[i].Mode.IsDir() {
141				// A nonempty directory may contain non-transcript artifacts.
142				_ = inventory.root.Remove(inventory.entries[i].Rel)
143			}
144		}
145		return nil
146	}

