1	#!/usr/bin/env bash
2	# tui-census.sh — capture every command's human-mode output for an eyeball pass.
3	#
4	# Enumerates the full command tree (via cobra __complete), runs each command in
5	# a small scratch repo under a fake TTY so colors are captured, and writes one
6	# file per command. Run it twice to compare renderings side by side:
7	#
8	#   scripts/tui-census.sh -b /path/to/old/entire-brain before
9	#   scripts/tui-census.sh after
10	#   # then: for f in .context/tui-census/after/*.txt; do less -R "$f" ...; done
11	#
12	# The scratch repo and its brain live under the output root and are shared
13	# between runs, so before/after differ only by rendering. Everything is
14	# isolated via ENTIRE_PLUGIN_*_DIR; nothing touches the real plugin store,
15	# and ENTIRE_BRAIN_NO_EGRESS=1 guarantees no hosted traffic.
16	#
17	# Commands that are interactive, mutating, networked, or token-spending are
18	# not executed; their file records the skip reason plus their --help output.
19	# A command missing from the table below is flagged UNMAPPED in its file so
20	# new commands surface in the census instead of silently vanishing.
21	set -euo pipefail
22	
23	ROOT="$(cd "$(dirname "$0")/.." && pwd)"
24	OUT_ROOT="$ROOT/.context/tui-census"
25	BIN=""
26	LABEL="current"
27	TIMEOUT_SECS=90
28	
29	while [ $# -gt 0 ]; do
30	  case "$1" in
31	    -b) BIN="$2"; shift 2 ;;
32	    -o) OUT_ROOT="$2"; shift 2 ;;
33	    -h|--help) sed -n '2,20p' "$0"; exit 0 ;;
34	    *) LABEL="$1"; shift ;;
35	  esac
36	done
37	
38	CAPTURE_DIR="$OUT_ROOT/$LABEL"
39	SCRATCH="$OUT_ROOT/scratch"
40	PLUGIN_DIRS="$OUT_ROOT/plugin-dirs"
41	mkdir -p "$CAPTURE_DIR" "$PLUGIN_DIRS"/{config,data,state,cache}
42	
43	if [ -z "$BIN" ]; then
44	  BIN="$OUT_ROOT/entire-brain-$LABEL"
45	  echo "building $BIN"
46	  (cd "$ROOT" && go build -o "$BIN" ./cmd/entire-brain)
47	fi
48	
49	# Environment for every invocation: colors on, default theme, no egress,
50	# isolated plugin store.
51	census_env() {
52	  env -u NO_COLOR -u ENTIRE_BRAIN_THEME \
53	    TERM=xterm-256color \
54	    ENTIRE_BRAIN_NO_EGRESS=1 \
55	    ENTIRE_PLUGIN_CONFIG_DIR="$PLUGIN_DIRS/config" \
56	    ENTIRE_PLUGIN_DATA_DIR="$PLUGIN_DIRS/data" \
57	    ENTIRE_PLUGIN_STATE_DIR="$PLUGIN_DIRS/state" \
58	    ENTIRE_PLUGIN_CACHE_DIR="$PLUGIN_DIRS/cache" \
59	    "$@"
60	}
61	
62	# Portable timeout (macOS has no coreutils timeout).
63	with_timeout() {
64	  perl -e 'alarm shift; exec @ARGV or die "exec: $!"' "$TIMEOUT_SECS" "$@"
65	}
66	
67	# ---------------------------------------------------------------- scratch repo
68	if [ ! -f "$SCRATCH/.census-ready" ]; then
69	  echo "setting up scratch repo at $SCRATCH"
70	  rm -rf "$SCRATCH"
71	  mkdir -p "$SCRATCH"
72	  (
73	    cd "$SCRATCH"
74	    git init -q -b main
75	    git config user.email census@example.invalid
76	    git config user.name "TUI Census"
77	    cat > main.go <<'GO'
78	package main
79	
80	import "fmt"
81	
82	func greet(name string) string { return "hello, " + name }
83	
84	func main() { fmt.Println(greet("census")) }
85	GO
86	    cat > README.md <<'MD'
87	# census-scratch
88	
89	Tiny repo used by scripts/tui-census.sh to exercise entire-brain commands.
90	MD
91	    git add main.go README.md
92	    git commit -qm "scratch: seed files"
93	  )
94	  (cd "$SCRATCH" && census_env "$BIN" refresh --agent none) || echo "warning: scratch refresh failed; captures will show degraded output"
95	  (cd "$SCRATCH" && census_env "$BIN" remember "The census scratch repo greets by name; greet() is the only API." --path project.notes.census --json >/dev/null) || true
96	  touch "$SCRATCH/.census-ready"
97	fi
98	
99	# ------------------------------------------------------------- command census
100	# run:<args>  — execute with these args (empty string means no args)
101	# skip:<why>  — do not execute; record the reason and --help instead
102	cmd_plan() {
103	  case "$1" in
104	    version|capabilities|doctor|status|stats|overview|agent-guide|verify|path|repo-identity|docs) echo "run:" ;;
105	    brief)       echo "run:'add a verbose flag to greet'" ;;
106	    query)       echo "run:greet" ;;
