112	    "entities history")    echo "run:greet" ;;
113	    "entities show")       echo "run:greet" ;;
114	    "config show"|"config path") echo "run:" ;;
115	    memories|"memories files"|"memories global"|"memories map"|"memories outline"|"memories status"|"memories tree"|"memories vitality"|"memories proposals list") echo "run:" ;;
116	    "memory status"|"memory jobs") echo "run:" ;;
