129	    "inspect tests")    echo "run:greet" ;;
130	    "inspect dead-code"|"inspect boundaries"|"inspect regressions") echo "run:" ;;
131	
132	    add)        echo "skip:clones a remote repository" ;;
133	    setup)      echo "skip:registers daemon/machine state" ;;
134	    dash)       echo "skip:full-screen interactive TUI" ;;
135	    mcp)        echo "skip:long-running server" ;;
136	    viz|"inspect graph-ui") echo "skip:starts a local web server" ;;
137	    watch|start|stop)       echo "skip:machine-wide background work" ;;
138	    connect|disconnect|publish) echo "skip:hosted egress" ;;
