140	    reset|gc|repair)        echo "skip:mutates or rebuilds the scratch brain mid-census" ;;
141	    refresh|"refresh delta"|"refresh history"|"refresh index"|"refresh sessions") echo "skip:already exercised during scratch setup" ;;
142	    remember)   echo "skip:writes a memory per census run (seeded once during scratch setup)" ;;
143	    config|"config init") echo "skip:writes plugin configuration" ;;
