145	    "memories proposals"|"memories proposals apply"|"memories proposals reject"|"memories proposals repair"|"memories proposals show") echo "skip:mutating or needs a proposal id" ;;
146	    memory|"memory abstract"|"memory cancel"|"memory configure"|"memory configure abstracts"|"memory migrate"|"memory notify"|"memory rebuild"|"memory reconcile"|"memory repair"|"memory retry") echo "skip:mutating or background-job control" ;;
147	    "privacy exclude"|"privacy include"|"privacy purge"|"privacy retention") echo "skip:mutates retention state" ;;
148	    "entities backfill"|"entities migrate") echo "skip:mutating migration" ;;
149	    bundle|"bundle export"|"bundle import") echo "skip:reads/writes bundle files" ;;
150	    webhook|"webhook test") echo "skip:sends a network request" ;;
151	    workspace|"workspace add"|"workspace create"|"workspace get"|"workspace inspect"|"workspace inspect context"|"workspace inspect graph"|"workspace inspect impact"|"workspace inspect regressions"|"workspace patterns"|"workspace patterns refresh"|"workspace patterns skills"|"workspace patterns skills form"|"workspace patterns status"|"workspace patterns verify"|"workspace query"|"workspace refresh"|"workspace remove"|"workspace review"|"workspace watch") echo "skip:needs a configured multi-repo workspace" ;;
152	    "inspect ingest-traces"|"inspect trace-path") echo "skip:needs trace input files" ;;
